const HISTORY_FOLDER_ID = '1Af1vO4a-8sec1_ou1evm_Q1YofC4Zj2o';

function requiredEnv(name) {
  const value = process.env[name];
  if (!value) throw new Error(`${name} is missing in n8n environment`);
  return value;
}

async function getAccessToken() {
  const response = await fetch('https://oauth2.googleapis.com/token', {
    method: 'POST',
    headers: { 'Content-Type': 'application/x-www-form-urlencoded' },
    body: new URLSearchParams({
      client_id: requiredEnv('GOOGLE_OAUTH_CLIENT_ID'),
      client_secret: requiredEnv('GOOGLE_OAUTH_CLIENT_SECRET'),
      refresh_token: requiredEnv('GOOGLE_OAUTH_REFRESH_TOKEN'),
      grant_type: 'refresh_token',
    }),
  });

  const payload = await response.json();
  if (!response.ok) throw new Error(`Google token failed: ${JSON.stringify(payload)}`);
  return payload.access_token;
}

const accessToken = await getAccessToken();
const q = `'${HISTORY_FOLDER_ID}' in parents and trashed = false and name contains '.json'`;
const listUrl = new URL('https://www.googleapis.com/drive/v3/files');
listUrl.searchParams.set('q', q);
listUrl.searchParams.set('fields', 'files(id,name,webViewLink,createdTime,modifiedTime)');
listUrl.searchParams.set('orderBy', 'createdTime desc');
listUrl.searchParams.set('pageSize', '50');

const listResponse = await fetch(listUrl, {
  headers: { Authorization: `Bearer ${accessToken}` },
});
const listPayload = await listResponse.json();
if (!listResponse.ok) throw new Error(`Drive list failed: ${JSON.stringify(listPayload)}`);

const history = [];
for (const file of listPayload.files || []) {
  const mediaResponse = await fetch(`https://www.googleapis.com/drive/v3/files/${file.id}?alt=media`, {
    headers: { Authorization: `Bearer ${accessToken}` },
  });
  if (!mediaResponse.ok) continue;
  try {
    const record = await mediaResponse.json();
    history.push({ ...record, history_file_id: file.id, history_file_url: file.webViewLink });
  } catch {}
}

history.sort((a, b) => new Date(b.uploaded_at || 0).getTime() - new Date(a.uploaded_at || 0).getTime());

return [{ json: { ok: true, history } }];
